monolith 2
# pine_forest.map -- a foggy pine forest at dusk. Design brief: MAP.md (read it first).
# Format: the header comment of runtime/monolith_scene.c (and AI-MAP-TOOL.md). Paths are
# relative to this folder. Asset provenance: ASSETS.md and models/*.asset.md.

# --- Materials: flat, muted dusk palette (low-poly style); only the forest floor is textured
material "default" albedo 120 116 110 roughness 0.9 metalness 0
# forest floor: ambientCG Ground037 (CC0), 2.1 m tile on the 200 m ground slab (600 / 2.1 = 286)
material "forest floor" albedo_map "textures/ground037_color.jpg" normal_map "textures/ground037_normal_gl.jpg"
material "forest floor" albedo 150 150 140 normal_scale 0.8 roughness 0.95 metalness 0 uv_scale 286 286 wrap repeat
material "needles" albedo 62 94 72 roughness 0.9 metalness 0
material "needles_dark" albedo 48 76 62 roughness 0.9 metalness 0
material "needles_blue" albedo 54 84 86 roughness 0.9 metalness 0
material "bark" albedo 80 64 58 roughness 0.95 metalness 0
material "wood" albedo 120 84 56 roughness 0.85 metalness 0
material "rock" albedo 84 82 86 roughness 0.85 metalness 0
material "moss" albedo 58 74 50 roughness 0.95 metalness 0
# Poly Haven rock face: keep only its normal map (the relief), colour from the palette
material "rock scan" albedo 98 94 94 roughness 0.85 metalness 0 inherit normal
material "canvas" albedo 150 96 62 roughness 0.9 metalness 0 cull none
material "camp stone" albedo 86 86 92 roughness 0.8 metalness 0
material "iron" albedo 40 40 44 roughness 0.6 metalness 0.6
material "embers" albedo 30 14 8 emission 255 110 40 emission_energy 5 roughness 1 metalness 0
# Poly Pizza lantern: keep its flat-colour atlas, not metallic
material "lantern" roughness 0.6 metalness 0.1 inherit albedo

# --- Environment: dusk. Low warm sun ahead-left of the path (light travels +Z, slightly +X),
# deep blue sky with an orange horizon, violet distance fog, sun shafts between the trunks.
env sky.mode procedural
env sky.size 1024
env sky.skyTopColor 26 38 80
env sky.skyHorizonColor 152 118 140
env sky.skyHorizonCurve 0.18
env sky.skyEnergy 1
env sky.groundBottomColor 58 62 90
env sky.groundHorizonColor 110 96 120
env sky.groundHorizonCurve 0.05
env sky.groundEnergy 1
env sky.sunColor 255 158 90
env sky.sunSizeDeg 2.2
env sky.sunCurve 0.08
env sky.sunEnergy 5
env ambientSky.mode procedural
env ambientSky.size 256
env ambientSky.groundBottomColor 96 88 86
env ambientSky.skyTopColor 92 112 160
env ambientSky.skyHorizonColor 150 136 150
env ambientSky.groundHorizonCurve 0.1
env sun.enabled on
env sun.direction 0.7 -0.32 0.64
env sun.color 255 164 100
env sun.energy 2.2
env sun.specular 0.6
env sun.fogEnergy 1.6
env sun.range 100
env sun.shadow on
env sun.softness 3
env sun.depthBias 0.0001
env sun.slopeBias 0.0015
env shadow.size 8192
env background.color 60 60 80
env background.energy 1
env background.skyBlur 0
env background.rotation 0 0 0 1
env ambient.color 0 0 0
env ambient.energy 1.5
env ssao.enabled on
env ssao.sampleCount 16
env ssao.intensity 1.2
env ssao.power 1
env ssao.radius 1.2
env ssao.bias 0.03
env ssil.enabled on
env ssil.sampleCount 16
env ssil.giIntensity 1.2
env ssil.aoIntensity 1
env ssil.aoPower 1
env ssil.radius 5
env ssil.bias 0.03
env ssgi.enabled off
env ssr.enabled off
env fog.mode exp2
env fog.color 62 70 102
env fog.start 1
env fog.end 50
env fog.density 0.022
env fog.skyAffect 0.35
env volumetricFog.enabled on
env volumetricFog.scatteringDensity 0.012
env volumetricFog.absortionDensity 0.001
env volumetricFog.scatteringColor 236 206 196
env volumetricFog.anisotropy 0.6
env volumetricFog.emissionColor 62 70 102
env volumetricFog.emissionEnergy 0.25
env volumetricFog.skyAffect 0.5
env volumetricFog.length 80
env volumetricFog.stepSize 0.75
env dof.mode disabled
env bloom.mode mix
env bloom.levels 0.5
env bloom.intensity 0.06
env bloom.threshold 0
env bloom.softThreshold 0.5
env bloom.filterRadius 1
env autoExposure.enabled off
env tonemap.mode agx
env tonemap.exposure 1.15
env tonemap.white 1
env color.brightness 1
env color.contrast 1.08
env color.saturation 0.9

# --- Player start (feet, yaw) and viewpoints (eye, target)
spawn 0 0 48 180
viewpoint "Forest path" 0 1.62 48 0 3 8
viewpoint "Campfire clearing" 7 1.7 9 -2 1.2 -2
viewpoint "Ridge lookout" 36 8.42 -27 0 -1 3
viewpoint "Meadow edge" -47 1.62 42 -12 5 0
viewpoint "Above the canopy" -26 24 50 2 4 -4

# --- Geometry
group "ground"
use "forest floor"
box -300 -1 -300 300 0 300

group "clearing: campfire"
use "default"
model "models/campfire.glb" 0 0 0 rot 20 0 0 scale 3.2 origin bottom material.0 "wood" material.1 "iron" material.2 "camp stone"
use "embers"
block 0 0 0 0.5 0.12 0.5
use "default"
light point 0 1.1 0 color 255 130 50 energy 5 range 18 falloff 1 fogEnergy 0.8 shadow on

group "clearing: camp"
model "models/tent.glb" -6.5 0 -4 rot 55 0 0 scale 5 origin bottom material.0 "wood" material.1 "canvas"
model "models/log.glb" 3.4 0 -1.6 rot 160 0 0 scale 3.6 origin bottom material.0 "bark" material.1 "wood"
model "models/log.glb" -0.8 0 3.8 rot 85 0 0 scale 3.4 origin bottom material.0 "bark" material.1 "wood"
model "models/stump_old.glb" -2.8 0 2.4 rot 30 0 0 scale 2.6 origin bottom material "bark"
model "models/lantern.glb" -2.8 0.69 2.4 rot 10 0 0 scale 0.45 origin bottom material "lantern" collide none
light point -2.8 1.0 2.4 color 255 180 110 energy 1.2 range 7 fogEnergy 1
model "models/lantern.glb" -4.2 0 -1.6 rot 80 0 0 scale 0.45 origin bottom material "lantern" collide none
light point -4.2 0.32 -1.6 color 255 180 110 energy 1 range 6 fogEnergy 1

group "path: lantern posts"
# 1.2 m wooden posts with a lantern on top, along the path from the spawn to the clearing
use "wood"
block 2.2 0 40 0.16 1.2 0.16
block -2.4 0 30 0.16 1.2 0.16
block 2.6 0 20 0.16 1.2 0.16
use "default"
model "models/lantern.glb" 2.2 1.2 40 rot 15 0 0 scale 0.45 origin bottom material "lantern" collide none
model "models/lantern.glb" -2.4 1.2 30 rot 75 0 0 scale 0.45 origin bottom material "lantern" collide none
model "models/lantern.glb" 2.6 1.2 20 rot 40 0 0 scale 0.45 origin bottom material "lantern" collide none
light point 2.2 1.55 40 color 255 180 110 energy 1.2 range 8 fogEnergy 1
light point -2.4 1.55 30 color 255 180 110 energy 1.2 range 8 fogEnergy 1
light point 2.6 1.55 20 color 255 180 110 energy 1.2 range 8 fogEnergy 1

group "ridge: terraces"
# Rock outcrop north-east of the clearing: three flat-topped terraces (y 2, 4.4, 6.8)
use "rock"
box 22 0 -42 52 2 -10
box 28 2 -40 52 4.4 -14
box 34 4.4 -38 52 6.8 -20
group "ridge: steps"
# 0.4 m steps climbing +X from the ground (x 17) to each terrace, z -28..-25
repeat 5 1 0.4 0 box 17 -1 -28 18 0.4 -25
repeat 6 1 0.4 0 box 22 1 -28 23 2.4 -25
repeat 6 1 0.4 0 box 28 3.4 -28 29 4.8 -25
use "default"
group "ridge: rock faces"
# Poly Haven rock_face_01 (normalised GLB), restyled to the palette, softening the box edges
model "models/rock_face_01.glb" 21 -0.4 -36 rot 90 0 0 scale 1.6 origin bottom material "rock scan"
model "models/rock_face_01.glb" 25 -0.3 -13 rot 200 0 0 scale 1.4 origin bottom material "rock scan"
model "models/rock_face_01.glb" 31 1.6 -40.5 rot 10 0 0 scale 1.5 origin bottom material "rock scan"
model "models/rock_face_01.glb" 33 3.8 -17 rot 160 0 0 scale 1.2 origin bottom material "rock scan"
model "models/rock_face_01.glb" 49 6.2 -36 rot 300 0 0 scale 1.3 origin bottom material "rock scan"

group "meadow: rocks"
# A grassy opening south-west, toward the last light
model "models/rock_largeD.glb" -42 0 33 rot 30 0 0 scale 4 origin bottom material.0 "rock" material.1 "moss" material.2 "rock"
model "models/rock_largeA.glb" -50 0 39 rot 120 0 0 scale 3.5 origin bottom material.0 "rock" material.1 "moss"
model "models/rock_largeA.glb" -38 0 44 rot 250 0 0 scale 2.5 origin bottom material.0 "rock" material.1 "moss"
model "models/stump_old.glb" -46 0 28 rot 200 0 0 scale 3 origin bottom material "bark"

